void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;                     // nothing to do

    // increase activity of the variable
    double delta = var_inc * coeff;
    activity[var] += delta;

    // overflow protection for the increment factor (rare)
    const double LIMIT = 1e100;
    if (var_inc > LIMIT) {
        const double SCALE = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // periodic lazy rescaling to keep activities bounded without per‑call overhead
    static const int RESCALE_INTERVAL = 100000;   // tune as needed
    static int bump_counter = 0;
    if (++bump_counter >= RESCALE_INTERVAL) {
        bump_counter = 0;
        const double SCALE = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
